class Member:
    def __init__(self, member_id: str, name: str, email: str):
        self.member_id = member_id
        self.name = name
        self.email = email
        self.active_loans = []

    def validate(self) -> bool:
        return bool(self.member_id and self.name and '@' in self.email)

class Loan:
    def __init__(self, loan_id: str, book: Book, member: Member, due_days: int = 14):
        self.loan_id = loan_id
        self.book = book
        self.member = member
        self.loan_date = datetime.now()
        self.due_date = self.loan_date + timedelta(days=due_days)
        self.return_date = None

    def is_overdue(self) -> bool:
        return datetime.now() > self.due_date and not self.return_date
